CREATE TABLE settings (
  key TEXT PRIMARY KEY,
  value JSONB NOT NULL,
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Example row:
{ key: 'ui:theme', value: 'dark', updated_at: '2024-01-01T12:00:00Z' }

CREATE TABLE daily_cache (
  date DATE PRIMARY KEY,
  payload JSONB NOT NULL,
  cached_at TIMESTAMPTZ DEFAULT NOW()
);

-- Example row:
{
  date: '2024-01-01',
  payload: {
    date: '2024-01-01',
    articles: [{url, title, read, removed, summary, ...}, ...],
    issues: [{date, source_id, category, ...}, ...]
  },
  cached_at: '2024-01-01T12:00:00Z'
}

-- Double-entry: each event is a debit + credit pair (IV_CARD_DEBIT / IV_CARD_CREDIT);
-- IV_SUM_IS is net of VAT. A raw SUM over all rows double-counts roughly 2x.
SELECT IV_VALUE_DATE, IV_SUM_IS, IV_CARD_DEBIT, IV_CARD_CREDIT
FROM account_invoices_tax
WHERE IV_COMPID = 1;

SELECT VALUE_DATE, SUPPLIER_CARD, SUM_IS, VAT_SUM
FROM account_supplier_invoices
WHERE COMPID = 1;

CREATE TABLE podcast_episodes (
  canonical_url TEXT PRIMARY KEY,
  audio_base64  TEXT NOT NULL,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
